import {createHash} from 'node:crypto';
import {address,createNoopSigner,getAddressEncoder,getProgramDerivedAddress,type Instruction} from '@solana/kit';
import {getMintDecoder,getCreateAssociatedTokenIdempotentInstruction,TOKEN_PROGRAM_ADDRESS} from '@solana-program/token';
import * as program from '../packages/client/src/program.ts';
import {MAX_U64,couponPerBond} from '../packages/client/src/domain.ts';
import {accountBytes,decodeTokenBalance,CLOCK_ADDRESS,type RpcAccount,type ReadRpc} from './chain-view.ts';
import {rpc,AppError} from './rpc.ts';
