export {normalizeV2Request,v2ActionNames};

type BondV2=ReturnType<typeof program.decodeBondV2>;
type ActionV2=ReturnType<typeof program.decodeActionV2>;
type SnapshotV2=ReturnType<typeof program.decodeSnapshotPageV2>;
type Token=ReturnType<typeof decodeTokenBalance>;
type ActionView={address:string;value:ActionV2;pages:SnapshotV2[];units:bigint[];claimed:boolean[];voted:boolean[];ballots:ReturnType<typeof program.decodeBallotV2>[]};
export type V2View={address:string;bond:BondV2;wallets:string[];holderRecords:ReturnType<typeof program.decodeHolderV2>[];holders:Token[];schedule:program.CouponTerms[];actions:ActionView[];bondMint:ReturnType<ReturnType<typeof getMintDecoder>['decode']>;settlementMint:ReturnType<ReturnType<typeof getMintDecoder>['decode']>;vault:Token;issuerSettlement:Token;clock:{slot:bigint;timestamp:bigint};contextSlot:number;startSlot:number;accountCount:number;proposalIds:string[];knownProposalIds:string[];omittedProposalIds:string[]};
export const V2_READ_BUDGET=4096;
const lengths={BondV2:319,HolderV2:77,RegistryPageV2:305,SchedulePageV2:241,ActionV2:235,SnapshotPageV2:123,BallotV2:82};
const pk=(s:string)=>Buffer.from(getAddressEncoder().encode(address(s)));
const u32=(n:number)=>{const b=Buffer.alloc(4);b.writeUInt32LE(n);return b;};
const u64=(n:bigint)=>{const b=Buffer.alloc(8);b.writeBigUInt64LE(n);return b;};
const discriminator=(name:string)=>createHash('sha256').update('account:'+name).digest().subarray(0,8);
function fail(code:string,message:string):never{throw new AppError(code,message,503);}
function check(ok:unknown,message:string):asserts ok{if(!ok)fail('RECONCILIATION_FAILED',message);}
function uint(n:bigint){check(n>=0n&&n<=MAX_U64,'Financial arithmetic exceeds u64');return n;}
const sum=(n:bigint[])=>n.reduce((a,b)=>uint(a+b),0n);
function slot(v:unknown):number{if(typeof v!=='number'||!Number.isSafeInteger(v)||v<0)fail('RPC_INVALID','Invalid RPC context slot');return v;}
async function confirmedAccount(key:string,minimum:number,request:ReadRpc){const result=await request('getAccountInfo',[key,{encoding:'base64',commitment:'confirmed',...(minimum?{minContextSlot:minimum}:{})}]),context=slot(result?.context?.slot);if(context<minimum||!Object.hasOwn(result??{},'value'))fail('RPC_INVALID','Confirmed account context regressed or omitted its value');return {value:result.value as RpcAccount|null,slot:context};}
